"""Display-only source checks/freeze. Never imports scientific source or results."""
import hashlib
import json
import subprocess
import time
from pathlib import Path
ROOT = Path.cwd()
OUT = ROOT / '.gcts-active/automatic-geometry-reader-source-v2-20261011'
NODE = '/Users/liuyao/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/bin/node'
def save(name, value):
    path = OUT / name
    with path.open('x') as stream:
        json.dump(value, stream, indent=2, ensure_ascii=True)
        stream.write('\n')
def pin(path):
    path = Path(path)
    return {'path': str(path.relative_to(ROOT)), 'sha256': hashlib.sha256(path.read_bytes()).hexdigest(), 'bytes': path.stat().st_size}
started = time.perf_counter()
syntax = subprocess.run([NODE, '--check', str(OUT / 'viewer.js')], capture_output=True, text=True, timeout=10)
(OUT / 'source-syntax-stderr.txt').write_text(syntax.stderr)
