(OUT / 'source-controls-stdout.txt').write_text(controls.stdout)
(OUT / 'source-controls-stderr.txt').write_text(controls.stderr)
checks_seconds = time.perf_counter() - started
if syntax.returncode or controls.returncode:
    raise RuntimeError('Display-only source check failed; preserved streams')
result = json.loads(controls.stdout)
save('source-controls.json', {'status': result['status'], 'syntax_exit_code': syntax.returncode, 'controls_exit_code': controls.returncode,
    'source_check_seconds': checks_seconds, 'controls': result, 'scope': 'Synthetic only; does not validate actual result data, browser layout, MathJax rendering, logical correctness or native acceptance.'})
old = ROOT / '.gcts-active/automatic-geometry-reader-source-20261011'
